CREATE SEQUENCE device_profiles_id_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;
CREATE SEQUENCE pack_items_id_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;
CREATE SEQUENCE packs_id_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;
CREATE SEQUENCE sample_features_id_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;
CREATE SEQUENCE samples_id_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;
CREATE SEQUENCE sononym_meta_id_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;
CREATE TABLE descriptors(sample_id INTEGER, provider VARCHAR, "name" VARCHAR, "value" FLOAT, PRIMARY KEY(sample_id, provider, "name"));
CREATE TABLE device_profiles(id INTEGER DEFAULT(nextval('device_profiles_id_seq')), device_id VARCHAR NOT NULL, "name" VARCHAR NOT NULL, yaml_path VARCHAR NOT NULL, config_json VARCHAR NOT NULL, last_used TIMESTAMP, PRIMARY KEY(id), UNIQUE(device_id));
CREATE TABLE labels(sample_id INTEGER, provider VARCHAR, kind VARCHAR, "label" VARCHAR, rank INTEGER NOT NULL, confidence FLOAT, PRIMARY KEY(sample_id, provider, kind, "label"));
CREATE TABLE missing_files(sample_id INTEGER, path VARCHAR NOT NULL, since INTEGER, PRIMARY KEY(sample_id));
CREATE TABLE samples(id INTEGER DEFAULT(nextval('samples_id_seq')), path VARCHAR NOT NULL, rel_path VARCHAR, filename VARCHAR NOT NULL, file_size_bytes INTEGER, file_hash VARCHAR, modified_at INTEGER, scanned_at TIMESTAMP DEFAULT(now()) NOT NULL, duration_s FLOAT, sample_rate INTEGER, channels INTEGER, bit_depth INTEGER, file_format VARCHAR, acid_bpm FLOAT, acid_beats INTEGER, root_note INTEGER, chunks_read INTEGER, is_favorite BOOLEAN NOT NULL, is_hidden BOOLEAN NOT NULL, user_tags VARCHAR, ableton_tags VARCHAR, PRIMARY KEY(id));
CREATE TABLE schema_version("version" INTEGER NOT NULL, applied_at VARCHAR NOT NULL);
CREATE TABLE walked_dirs(path VARCHAR, mtime_ns BIGINT NOT NULL, listing VARCHAR NOT NULL, PRIMARY KEY(path));
CREATE TABLE packs(id INTEGER DEFAULT(nextval('packs_id_seq')), "name" VARCHAR NOT NULL, device_id INTEGER, description VARCHAR, created_at TIMESTAMP DEFAULT(now()) NOT NULL, export_path VARCHAR, skill_params VARCHAR, PRIMARY KEY(id), FOREIGN KEY (device_id) REFERENCES device_profiles(id));
CREATE TABLE pack_items(id INTEGER DEFAULT(nextval('pack_items_id_seq')), pack_id INTEGER NOT NULL, sample_id INTEGER NOT NULL, dest_folder VARCHAR, dest_filename VARCHAR, slot_name VARCHAR, cv_role VARCHAR, sort_order INTEGER NOT NULL, PRIMARY KEY(id), UNIQUE(pack_id, sample_id), FOREIGN KEY (pack_id) REFERENCES packs(id), FOREIGN KEY (sample_id) REFERENCES samples(id));
CREATE TABLE sample_features(id INTEGER DEFAULT(nextval('sample_features_id_seq')), sample_id INTEGER NOT NULL, computed_at TIMESTAMP, sub_weight FLOAT, transient_score FLOAT, loop_confidence FLOAT, is_pitched INTEGER, bpm_reliable INTEGER, bpm_corrected FLOAT, timbral_norm VARCHAR, derived_computed_at TIMESTAMP, spectral_balance FLOAT, pitch_stability INTEGER, attack_class VARCHAR, drum_subtype VARCHAR, spectral_centroid_mean FLOAT, spectral_bandwidth_mean FLOAT, spectral_rolloff_mean FLOAT, spectral_flatness_mean FLOAT, zero_crossing_rate_mean FLOAT, rms_mean FLOAT, tempo_bpm FLOAT, onset_rate_hz FLOAT, mfcc_mean VARCHAR, attack_time_ms FLOAT, decay_time_ms FLOAT, harmonic_percussive_ratio FLOAT, chroma_concentration FLOAT, is_clipped INTEGER, dc_offset_ratio FLOAT, clap_embedding BLOB, clap_model VARCHAR, detected_key VARCHAR, key_confidence FLOAT, trim_end_s FLOAT, trim_computed_at TIMESTAMP, n_events INTEGER, event_regularity FLOAT, event_echo INTEGER, events_computed_at TIMESTAMP, PRIMARY KEY(id), UNIQUE(sample_id), FOREIGN KEY (sample_id) REFERENCES samples(id));
CREATE TABLE sononym_meta(id INTEGER DEFAULT(nextval('sononym_meta_id_seq')), sample_id INTEGER NOT NULL, sononym_asset_id INTEGER, classes VARCHAR, class_strengths VARCHAR, categories VARCHAR, category_strengths VARCHAR, pitch_class VARCHAR, base_note FLOAT, base_note_confidence FLOAT, peak_db FLOAT, rms_db FLOAT, crest_factor FLOAT, bpm FLOAT, bpm_confidence FLOAT, brightness FLOAT, noisiness FLOAT, harmonicity FLOAT, class_signature VARCHAR, category_signature VARCHAR, pitch_confidence FLOAT, PRIMARY KEY(id), UNIQUE(sample_id), FOREIGN KEY (sample_id) REFERENCES samples(id));
CREATE INDEX idx_samples_format ON samples(file_format);
CREATE INDEX ix_descriptors_provider_name ON descriptors(provider, "name");
CREATE INDEX ix_labels_provider_kind_label ON labels(provider, kind, "label");
CREATE INDEX ix_samples_filename ON samples(filename);
CREATE INDEX ix_samples_file_hash ON samples(file_hash);
CREATE UNIQUE INDEX ix_samples_path ON samples(path);
CREATE INDEX ix_samples_rel_path ON samples(rel_path);
CREATE INDEX ix_sononym_meta_bpm ON sononym_meta(bpm);
CREATE INDEX ix_sononym_meta_sononym_asset_id ON sononym_meta(sononym_asset_id);
